<script>
import { ref, computed, onMounted } from 'vue';
import { useToast } from 'vue-toastification';
import { formatCurrency } from '@/utils/formatters';
import { accountService } from '@/services/accountService';
import { logoff } from '@/services/auth/loginService';

export default {
  name: 'DashboardView',
  emits: ['change-view'],
  setup(props, { emit }) {
    const toast = useToast();
    const overdueCards = ref({});
    const loading = ref(true);
    const showOverdue = ref(false);

    const totalOverdueCount = computed(() =>
      Object.values(overdueCards.value).reduce((sum, v) => sum + v.count, 0)
    );

    const totalOverdueAmount = computed(() =>
      Object.values(overdueCards.value).reduce((sum, v) => sum + v.totalAmount, 0)
    );

    onMounted(fetchOverdueAccounts);

    async function fetchOverdueAccounts() {
      try {
        const user = await accountService.getCurrentUser();
        if (!user) return;
        const grouped = await accountService.fetchOverdueAccounts();
        overdueCards.value = grouped;
      } catch (err) {
        console.error('Erro ao buscar contas:', err.message);
        toast.error('Erro ao carregar dados do dashboard.');
      } finally {
        loading.value = false;
      }
    }

    function toggleOverdue() {
      showOverdue.value = !showOverdue.value;
    }

    async function handleLogout() {
      await logoff();
      emit('change-view', 'Login');
    }

    return {
      overdueCards,
      loading,
      showOverdue,
      totalOverdueCount,
      totalOverdueAmount,
      formatCurrency,
      toggleOverdue,
      handleLogout,
    };
  },
};
</script>

