<template>
  <button
    :type="type"
    :disabled="disabled || loading"
    :class="buttonClasses"
    @click="$emit('click', $event)"
  >
    <span v-if="loading" class="spinner-border spinner-border-sm me-2" role="status" aria-hidden="true" />
    <span v-if="icon && !loading" class="btn-icon">
      <slot name="icon" />
    </span>
    <span v-if="!iconOnly || loading">
      <slot />
    </span>
  </button>
</template>

<script>
export default {
  name: 'BaseButton',
  props: {
    variant: {
      type: String,
      default: 'primary',
      validator: (v) => ['primary', 'secondary', 'ghost', 'danger', 'success', 'outline'].includes(v),
    },
    size: {
      type: String,
      default: 'md',
      validator: (v) => ['sm', 'md', 'lg'].includes(v),
    },
    loading: { type: Boolean, default: false },
    disabled: { type: Boolean, default: false },
    iconOnly: { type: Boolean, default: false },
    block: { type: Boolean, default: false },
    type: { type: String, default: 'button' },
    icon: { type: Boolean, default: false },
  },
  emits: ['click'],
  computed: {
    buttonClasses() {
      return [
        'btn',
        `btn-${this.size}`,
        this.variantClasses,
        { 'w-100': this.block },
        { 'btn-icon-only': this.iconOnly },
      ];
    },
    variantClasses() {
      const map = {
        primary: 'btn-accent',
        secondary: 'btn-outline-secondary',
        ghost: 'btn-ghost',
        danger: 'btn-danger-custom',
        success: 'btn-success-custom',
        outline: 'btn-outline-accent',
      };
      return map[this.variant] || 'btn-accent';
    },
  },
};
</script>

