          <div class="input-group">
            <span class="input-group-text">R$</span>
            <input
              v-model="monthlySalary"
              type="number"
              class="form-control"
              placeholder="0,00"
            />
          </div>
        </div>
        <div class="col-md-4">
          <label class="summary-label">Total de contas (pendentes)</label>
          <div class="input-group">
            <span class="input-group-text">R$</span>
            <input
              :value="totalAccounts"
              type="text"
              class="form-control"
              readonly
            />
          </div>
        </div>
        <div class="col-md-4">
          <label class="summary-label">Valor restante</label>
          <div class="input-group">
            <span class="input-group-text">R$</span>
            <input
              :value="remainingBalance"
              type="text"
              class="form-control"
              :class="balanceClass"
              readonly
            />
          </div>
        </div>
      </div>
    </div>

    <!-- Filters -->
    <div class="d-flex flex-wrap gap-3 mb-4">
      <select
        v-model="selectedYear"
        class="form-select filter-select"
        aria-label="Selecione o ano"
        @change="fetchAccounts"
      >
        <option value="" disabled>Selecione o ano</option>
        <option v-for="year in years" :key="year" :value="year">
          {{ year }}
        </option>
      </select>

      <select
        v-model="selectedMonth"
        class="form-select filter-select"
        aria-label="Selecione o mês"
        :disabled="!selectedYear"
        @change="
          () => {
            fetchAccounts();
            setMonthlySalaryToMonth(selectedMonth);
          }
        "
      >
        <option value="" disabled>Selecione o mês</option>
        <option v-for="(month, index) in months" :key="index" :value="index">
          {{ month }}
        </option>
      </select>
    </div>

    <!-- Error -->
    <div v-if="error" class="alert alert-danger text-center">{{ error }}</div>

    <!-- Loading -->
    <div v-if="loading" class="table-wrapper p-3">
      <div v-for="n in 6" :key="n" class="skeleton mb-2" style="height: 44px;" />
    </div>

    <!-- Empty state -->
    <div v-else-if="accounts.length === 0" class="empty-state-table">
      <svg xmlns="http://www.w3.org/2000/svg" width="48" height="48" fill="currentColor" class="bi bi-inbox mb-3" viewBox="0 0 16 16">
        <path d="M4.98 4a.5.5 0 0 0-.39.188L1.54 8H6a.5.5 0 0 1 .5.5 1.5 1.5 0 1 0 3 0A.5.5 0 0 1 10 8h4.46l-3.05-3.812A.5.5 0 0 0 11.02 4H4.98zm9.954 5H10.45a2.5 2.5 0 0 1-4.9 0H1.066l.32 2.562a.5.5 0 0 0 .497.438h12.234a.5.5 0 0 0 .497-.438L14.934 9zM3.809 3.563A1.5 1.5 0 0 1 4.981 3h6.038a1.5 1.5 0 0 1 1.172.563l3.7 4.625a.5.5 0 0 1 .105.374l-.39 3.124A1.5 1.5 0 0 1 14.117 13H1.883a1.5 1.5 0 0 1-1.489-1.314l-.39-3.124a.5.5 0 0 1 .106-.374l3.7-4.625z"/>
      </svg>
      <p class="text-muted">Nenhuma conta encontrada para este mês.</p>
    </div>

    <!-- Desktop Table -->
    <div v-else class="table-wrapper">
      <table class="table table-hover align-middle mb-0">
        <thead>
          <tr>
            <th>Conta</th>
            <th>Dia</th>
            <th>Parcela</th>
            <th>Valor</th>
            <th>Vencimento</th>
            <th>Pagamento</th>
            <th>Status</th>
            <th></th>
          </tr>
        </thead>
        <tbody>
          <tr v-for="parcela in accounts" :key="parcela.id">
            <!-- Conta -->
            <td>
              <span class="account-name">{{ parcela.account.ds_nome }}</span>
            </td>

            <!-- Dia Vencimento -->
            <td>
              <span class="text-muted small">{{ parcela.account.dia_vencimento }}</span>
            </td>

            <!-- Nº Parcela -->
            <td>
              <span class="badge bg-secondary bg-opacity-25 text-secondary fw-semibold">
                {{ parcela.numero_parcela }}
              </span>
            </td>

            <!-- Valor Parcela -->
            <td>
              <input
                v-if="parcela.isEditingValor_parcela"
                v-model="parcela.valor_parcela"
                type="number"
                class="form-control form-control-sm edit-input"
                @blur="saveEdit(parcela, 'valor_parcela')"
                @keyup.enter="saveEdit(parcela, 'valor_parcela')"
              />
              <span
                v-else
                class="editable-cell"
                @click="edit(parcela, 'valor_parcela')"
              >
                {{ formatCurrency(parcela.valor_parcela) }}
              </span>
            </td>

            <!-- Data Vencimento -->
            <td>
              <input
                v-if="parcela.isEditingDt_vencimento"
                v-model="parcela.dt_vencimento"
                type="date"
                class="form-control form-control-sm edit-input"
                @blur="saveEdit(parcela, 'dt_vencimento')"
              />
              <span
                v-else
                class="editable-cell"
                @click="edit(parcela, 'dt_vencimento')"
              >
                {{ formatDate(parcela.dt_vencimento) }}
              </span>
            </td>

            <!-- Data Pagamento -->
            <td>
              <input
                v-if="parcela.isEditingDt_pagamento"
                v-model="parcela.dt_pagamento"
                type="date"
                class="form-control form-control-sm edit-input"
                @blur="saveEdit(parcela, 'dt_pagamento')"
              />
              <span
                v-else
                class="editable-cell"
                @click="edit(parcela, 'dt_pagamento')"
              >
                {{ parcela.dt_pagamento ? formatDate(parcela.dt_pagamento) : '--' }}
              </span>
            </td>

            <!-- Status -->
            <td>
              <select
                v-if="parcela.isEditingStatus"
                v-model="parcela.status"
                class="form-select form-select-sm edit-input"
                @blur="saveEdit(parcela, 'status')"
              >
                <option value="Pendente">Pendente</option>
                <option value="Pago">Pago</option>
                <option value="Atrasado">Atrasado</option>
              </select>
              <span
                v-else
                class="editable-cell"
                @click="edit(parcela, 'status')"
              >
                <BaseBadge :variant="statusVariant(parcela.status)" size="sm">
                  {{ parcela.status }}
                </BaseBadge>
              </span>
            </td>

            <!-- Delete -->
            <td class="text-end">
              <button
                class="btn-delete"
                title="Excluir parcela"
                @click="confirmDelete(parcela)"
              >
