<script>
import supabase from '@/utils/supabase';
import { computed, ref, watch } from 'vue';
import { useToast } from 'vue-toastification';
import { formatCurrency, formatDate, getMonths, getYears } from '@/utils/formatters';
import BaseBadge from '@/components/ui/BaseBadge.vue';
import BaseModal from '@/components/ui/BaseModal.vue';

export default {
  name: 'ListarView',
  components: { BaseBadge, BaseModal },
  setup() {
    const toast = useToast();
    const loading = ref(false);
    const error = ref(null);
    const accounts = ref([]);
    const monthlySalary = ref(0);
    const totalAccounts = ref(0);
    const selectedYear = ref(new Date().getFullYear());
    const selectedMonth = ref(null);
    const showDeleteModal = ref(false);
    const parcelaToDelete = ref(null);

    const years = computed(() => getYears());
    const months = computed(() => getMonths());

    const remainingBalance = computed(() => {
      const result = monthlySalary.value - totalAccounts.value;
      return result.toFixed(2);
    });

    const balanceClass = computed(() => ({
      'text-success': remainingBalance.value > 0,
      'text-danger': remainingBalance.value < 0,
    }));

    watch(selectedMonth, (newMonth) => {
      if (newMonth !== null) {
        const savedSalary = localStorage.getItem(`monthlySalary-${newMonth}`);
        monthlySalary.value = savedSalary ? JSON.parse(savedSalary) : 0;
      }
    });

    watch(monthlySalary, (newSalary) => {
      if (selectedMonth.value !== null) {
        localStorage.setItem(
          `monthlySalary-${selectedMonth.value}`,
          JSON.stringify(newSalary)
        );
      }
    });

    async function fetchAccounts() {
      if (selectedMonth.value === null || !selectedYear.value) return;

      loading.value = true;
      error.value = null;

      try {
        const {
          data: { user },
          error: authError,
        } = await supabase.auth.getUser();
        if (authError) throw authError;

        if (user) {
          const startOfMonth = new Date(
            selectedYear.value,
            selectedMonth.value,
            1
          ).toISOString();
          const endOfMonth = new Date(
            selectedYear.value,
            selectedMonth.value + 1,
            0
          ).toISOString();

          const { data: accountsResult, error: accountsError } = await supabase
            .from('account_parcelas')
            .select('*, account:id_account(*)')
            .eq('account.user_id', user.id)
            .gte('dt_vencimento', startOfMonth)
            .lte('dt_vencimento', endOfMonth)
            .order('dt_vencimento', { ascending: true });

          if (accountsError) {
            toast.error('Ocorreu um erro ao buscar as contas');
          }

          const result = (accountsResult || []).map((conta) => ({
            ...conta,
            status: conta.dt_pagamento
              ? 'Pago'
              : validateStatus(conta.dt_vencimento),
          }));

          totalAccounts.value = Number(
            result
              .filter((item) => item.status !== 'Pago')
              .reduce((acc, item) => acc + Number(item.valor_parcela || 0), 0)
          ).toFixed(2);

          accounts.value = result;
        }
      } catch (err) {
        console.error('Erro ao buscar contas:', err.message);
        error.value = 'Ocorreu um erro ao buscar as contas';
        toast.error(error.value);
      } finally {
        loading.value = false;
      }
    }

    function confirmDelete(parcela) {
      parcelaToDelete.value = parcela;
      showDeleteModal.value = true;
    }

    async function handleDeleteConfirm() {
      if (!parcelaToDelete.value) return;
      await deletarParcela(parcelaToDelete.value.id);
      showDeleteModal.value = false;
      parcelaToDelete.value = null;
    }

    async function deletarParcela(parcelaId) {
      const { error: deleteError } = await supabase
        .from('account_parcelas')
        .delete()
        .eq('id', parcelaId);

      if (deleteError) {
        toast.error('Ocorreu um erro ao excluir a parcela');
      } else {
        toast.success('Parcela excluída com sucesso');
      }
      fetchAccounts();
    }

    function edit(parcela, field) {
      const editKey = `isEditing${field.charAt(0).toUpperCase() + field.slice(1)}`;
      const originalKey = `original${field.charAt(0).toUpperCase() + field.slice(1)}`;
      parcela[editKey] = true;
      parcela[originalKey] = parcela[field];
    }

    async function saveEdit(parcela, field) {
      const originalKey = `original${field.charAt(0).toUpperCase() + field.slice(1)}`;
      const originalValue = parcela[originalKey];
      const newValue = parcela[field];

      if (originalValue !== newValue) {
        const updateData = { [field]: newValue };

        if (field === 'status' && newValue === 'Pago' && originalValue !== 'Pago') {
          const today = new Date().toISOString().split('T')[0];
          parcela.dt_pagamento = today;
          updateData.dt_pagamento = today;
          monthlySalary.value = Number(
            (monthlySalary.value - parcela.valor_parcela).toFixed(2)
          );
        }

        const { error } = await supabase
          .from('account_parcelas')
          .update(updateData)
          .eq('id', parcela.id);

        if (error) {
          toast.error('Ocorreu um erro ao salvar a alteração');
        } else {
          toast.success('Alteração salva com sucesso!');
          recalcTotalAccounts();
        }
      }

      const editKey = `isEditing${field.charAt(0).toUpperCase() + field.slice(1)}`;
      parcela[editKey] = false;
    }

    function validateStatus(dataVencimento) {
      const dataAtual = new Date();
      const dataVencimentoFormatada = new Date(dataVencimento);
      if (dataVencimentoFormatada < dataAtual) {
        return 'Atrasado';
      }
      return 'Pendente';
    }

    function statusVariant(status) {
      const map = { Pago: 'success', Pendente: 'warning', Atrasado: 'danger' };
      return map[status] || 'neutral';
    }

    function recalcTotalAccounts() {
      totalAccounts.value = accounts.value
        .filter((item) => item.status !== 'Pago')
        .reduce((acc, item) => acc + Number(item.valor_parcela || 0), 0)
        .toFixed(2);
    }

    function setMonthlySalaryToMonth(index) {
      const savedSalary = localStorage.getItem(`monthlySalary-${index}`);
      monthlySalary.value = savedSalary ? JSON.parse(savedSalary) : 0;
    }

    return {
      accounts,
      months,
      selectedMonth,
      loading,
      error,
      formatCurrency,
      formatDate,
      fetchAccounts,
      confirmDelete,
      handleDeleteConfirm,
      deletarParcela,
      edit,
      saveEdit,
      monthlySalary,
      totalAccounts,
      remainingBalance,
      balanceClass,
      recalcTotalAccounts,
      setMonthlySalaryToMonth,
      years,
      selectedYear,
      showDeleteModal,
      statusVariant,
    };
  },
};
</script>

