<template>
  <span :class="badgeClasses">
    <span v-if="pulse" class="pulse-dot" />
    <slot />
  </span>
</template>

<script>
export default {
  name: 'BaseBadge',
  props: {
    variant: {
      type: String,
      default: 'neutral',
      validator: (v) =>
        ['success', 'warning', 'danger', 'info', 'neutral'].includes(v),
    },
    size: {
      type: String,
      default: 'md',
      validator: (v) => ['sm', 'md'].includes(v),
    },
    pulse: { type: Boolean, default: false },
  },
  computed: {
    badgeClasses() {
      return [
        'badge-custom',
        `badge-${this.variant}`,
        `badge-${this.size}`,
        { 'badge-pulse': this.pulse },
      ];
    },
  },
};
</script>

