.badge-success {
  background: var(--am-success-bg);
  color: var(--am-success);
}
.badge-warning {
  background: var(--am-warning-bg);
  color: var(--am-warning);
}
.badge-danger {
  background: var(--am-danger-bg);
  color: var(--am-danger);
}
.badge-info {
  background: var(--am-info-bg);
